    for row in ws.iter_rows():
        for cell in row:
            if isinstance(cell.value, str) and cell.value.startswith('=') and 'PWT' in cell.value:
                refs.append((ws.title, cell.coordinate, cell.value))

print(refs[:50])
print('count', len(refs))
